using DotsKit.Generation;
using DotsKit.Io;
using DotsKit.Planning;
using DotsKit.Solutions;

namespace DotsKit.Commands;

/// <summary>
/// <c>dotskit upgrade</c>: brings a solution to the tool's version of the template, keeping what the team changed.
/// The same three-way merge as dotskit new, with the solution's manifest generated by its own version as the base
/// and by the tool's, or the release --to names, as the target; the files the template moved take the team's
/// changes with them, and the package versions follow the manifest's policy. It takes the parts of
/// <see cref="UpgradeParts"/> one after another in one run, each committed before the next, and stops at the
/// first part whose merge leaves conflicts; --continue resumes there, and --all-at-once merges every part in
/// one run.
/// </summary>
/// <param name="planner">Builds the plan: the trees of the template, their merge with the solution and the report.</param>
/// <param name="execution">Shows the plan, asks, writes it and builds.</param>
/// <param name="git">Tells whether the solution's working tree is clean, and whether it is at the root of its repository, before anything is written.</param>
/// <param name="ignored">The files the solution's git ignores: a folder of them, as TestResults, is no part of an upgrade.</param>
/// <param name="terminal">Says where the solution goes from and to, or that it is there already.</param>
/// <param name="toolVersion">The version of the tool, where an upgrade goes when --to names no release.</param>
/// <param name="onSources">The tool runs against the template's sources: it upgrades any release to them.</param>
internal sealed class UpgradeCommand(IPlanner planner, PlanExecution execution, IGit git, Merging.IIgnoredFiles ignored, ITerminal terminal, string toolVersion, bool onSources)
{
    public async Task<ExitCode> RunAsync(Options options, string folder, CancellationToken ct)
    {
        if (options.TemplateArgs.Count > 0)
        {
            throw new ArgumentException($"dotskit upgrade takes no parameter of the template; leave out {string.Join(' ', options.TemplateArgs)}: dotskit new adds a service or a flag.");
        }

        var root = SolutionRoot.Find(folder)
            ?? throw new InvalidOperationException($"No solution here: dotskit upgrade runs in a solution, a folder with {Layout.ServicesFolder}/{Layout.SolutionPattern} or below it.");
        var current = Manifest.Load(root)
            ?? throw new InvalidOperationException($"{Layout.ManifestPath} is missing: describe the solution first, dotskit init.");
        if (current.Upgrade is { } inProgress)
        {
            // The tool may have changed since the upgrade began: the release it goes to is checked again on every run.
            CheckTarget(current, inProgress.To);
            return await NextPartAsync(root, current, inProgress, options, ct);
        }

        if (options.Continue)
        {
            throw new InvalidOperationException("No upgrade is in progress: dotskit upgrade --continue continues an upgrade stopped at its conflicts; run dotskit upgrade to start one.");
        }

        var target = options.To ?? DefaultTarget;
        if (current.Template == target)
        {
            terminal.Info($"The solution is of the template {target} already.");
            return ExitCode.Done;
        }

        CheckTarget(current, target);
        if (!options.AllAtOnce)
        {
            return await NextPartAsync(root, current, new UpgradeInProgress { To = target, Done = [] }, options, ct);
        }

        await GitPreconditions.CheckAsync(git, root, options, ct);
        return await WithUncommittedAsync(root, options, async () =>
        {
            var start = await TreeStart.OfAsync(git, root, options, ct);

            terminal.Info($"Upgrading the solution from the template {current.Template} to {target}.");
            terminal.Info(UpgradeGuide.Of(current.Template, target));
            var plan = await planner.BuildAsync(root, current, current.WithTemplate(target).Widened(), new Merging.MergeMode(options.Force, options.MarkBase), ct);
            return await execution.RunAsync(plan, options, start, ct);
        }, ct);
    }

    /// <summary>Where an upgrade goes when --to names no release: the tool's version, or the template's sources.</summary>
    private string DefaultTarget => onSources ? TemplateSource.SourcesVersion : toolVersion;

    /// <summary>
    /// --allow-dirty: the uncommitted changes committed by plumbing beside the run, so the merge runs on them and they
    /// take part in it; undone by <c>git reset --mixed</c> when the run fails before the merge stands - an open merge
    /// keeps them: it commits them with the upgrade.
    /// </summary>
    private async Task<ExitCode> WithUncommittedAsync(string root, Options options, Func<Task<ExitCode>> run, CancellationToken ct)
    {
        var uncommitted = options.AllowDirty
            ? await git.CommitUncommittedAsync(root, "dotskit: uncommitted changes, taken into the upgrade", ct)
            : null;
        try
        {
            return await run();
        }
        catch (Exception failure)
        {
            if (uncommitted is { } taken && !await git.MergeInProgressAsync(root, ct))
            {
                try
                {
                    await git.UncommitAsync(root, taken.Previous, ct);
                }
                catch (Exception uncommit)
                {
                    throw new InvalidOperationException(
                        $"{failure.Message} The uncommitted changes are left committed as {taken.Commit[..7]}: run git reset --mixed {taken.Previous} to put them back uncommitted.", uncommit);
                }
            }

            throw;
        }
    }

    /// <summary>Refuses an upgrade to <paramref name="to"/> this tool cannot make, with what to do instead.</summary>
    private void CheckTarget(Manifest current, string to)
    {
        var from = current.Template;
        if (TemplateVersions.WhyNotUpgraded(from, toolVersion, onSources) is { } why)
        {
            throw new InvalidOperationException(why);
        }

        if (to != DefaultTarget && TemplateVersions.WhyNotTarget(from, to, toolVersion, onSources) is { } whyNotTo)
        {
            throw new InvalidOperationException(whyNotTo);
        }

        var messaging = current.ServiceArgs
            .Select(service => (Line: $"of the service {service.Service}", Value: service["Messaging"]))
            .Append((Line: "of the solution", Value: current.SolutionArgs["Messaging"]));
        foreach (var (line, value) in messaging)
        {
            if (TemplateVersions.WhyNotATransport(value, to) is { } whyNotATransport)
            {
                throw new InvalidOperationException($"{whyNotATransport} The line {line} in {Layout.ManifestPath}: edit it, then run dotskit upgrade again.");
            }
        }
    }

    /// <summary>
    /// An upgrade a part at a time: the template's next output of the parts merged before and this one, merged over
    /// its output of the parts before. Each part written and built is committed and the next one follows in this run,
    /// until the merge of a part leaves conflicts: then the run stops, one line says how much is left and how it goes
    /// on (<c>dotskit upgrade --continue</c>), and the manifest keeps the part out of Done, so it names only the
    /// parts whose merge is committed: the run after the resolution takes the part again, and Done takes it once its
    /// merge is committed. The last part moves the version, unless it leaves conflicts: then the run after their
    /// resolution finishes the upgrade.
    /// </summary>
    private async Task<ExitCode> NextPartAsync(string root, Manifest current, UpgradeInProgress upgrade, Options options, CancellationToken ct)
    {
        if (options.To is not null && options.To != upgrade.To)
        {
            throw new InvalidOperationException($"An upgrade to {upgrade.To} goes a part at a time: finish it, dotskit upgrade, before --to {options.To}.");
        }

        if (options.AllAtOnce)
        {
            throw new InvalidOperationException($"An upgrade to {upgrade.To} goes a part at a time already: finish it, dotskit upgrade, without --all-at-once.");
        }

        await GitPreconditions.CheckAsync(git, root, options, ct);
        return await WithUncommittedAsync(root, options, async () =>
        {
            // What the solution's git ignores is not the solution: a TestResults left by a test run is no part.
            var leftAlone = await ignored.InAsync(root, ct);
            var files = Folders.RelativeFiles(root).Where(f => !leftAlone.Contains(f)).ToList();
            IReadOnlyList<string> parts = upgrade.Parts ?? UpgradeParts.In(files, CommonReferences.Read(root, files));
            if (upgrade.Parts is not null && UpgradeParts.In(files).Except(parts).ToList() is [_, ..] appeared)
            {
                throw new InvalidOperationException($"{string.Join(", ", appeared)} appeared after the upgrade to {upgrade.To} began, and is no part of it: "
                    + "move it out until the upgrade is finished, then put it back.");
            }

            while (true)
            {
                var (code, merged) = await RunPartAsync(root, current, upgrade, parts, options, ct);
                if (code == ExitCode.Conflicts)
                {
                    return ExitCode.Conflicts;
                }

                if (code != ExitCode.Done || options.Part is not null)
                {
                    return code;
                }

                // The part stands: commit it, so the next part merges over it, and read what the step wrote. The commit
                // the part ends the upgrade with says so: a part left in conflict and resolved is taken again, and its
                // second run moves the version, not the finish step.
                current = Manifest.Load(root)!;
                await git.CommitAsync(root, merged is { } part && current.Upgrade is not null
                    ? $"dotskit: the upgrade to {upgrade.To}, part {part}"
                    : $"dotskit: the upgrade to {upgrade.To}, finished", ct);
                if (current.Upgrade is not { } next)
                {
                    return ExitCode.Done;
                }

                upgrade = next;
                parts = upgrade.Parts ?? parts;
            }
        }, ct);
    }

    /// <summary>
    /// One step of an upgrade: the finish after every part is merged, or the merge of the next part, named by what it
    /// merged. On conflicts it writes the manifest that keeps the upgrade open and names what is left and how the
    /// upgrade goes on.
    /// </summary>
    private async Task<(ExitCode Code, string? Merged)> RunPartAsync(string root, Manifest current, UpgradeInProgress upgrade, IReadOnlyList<string> parts, Options options, CancellationToken ct)
    {
        var start = await TreeStart.OfAsync(git, root, options, ct);
        var target = (current.WithTemplate(upgrade.To).Widened()) with { Upgrade = null };
        if (options.Part is null && parts.All(upgrade.Done.Contains))
        {
            return (await FinishAsync(root, current, upgrade, parts, options, start, ct), null);
        }

        var part = UpgradeParts.Next(parts, upgrade.Done, options.Part);
        if (upgrade.Done.Count == 0)
        {
            terminal.Info(UpgradeGuide.Of(current.Template, upgrade.To));
        }

        var plan = await planner.BuildAsync(root, current with { Upgrade = null }, target, new Merging.MergeMode(options.Force, options.MarkBase), ct,
            new PartStep(upgrade.Done.ToHashSet(StringComparer.Ordinal), part, upgrade.Parts));
        // The first run takes the parts from the template's next output too: a project it adds is a part, possibly after
        // this one, so the count is said once the plan has them.
        var all = plan.Parts ?? parts;
        var last = !all.Any(p => !upgrade.Done.Contains(p) && p != part);
        terminal.Info($"Upgrading the solution from the template {current.Template} to {upgrade.To}, a part at a time: {part}, "
            + $"{upgrade.Done.Count + 1} of {all.Count}{(last ? ", the last" : "")}.");
        var next = current.WithPartMerged(upgrade.To, part, last, all);
        var step = plan with
        {
            // The last part moves the solution to the target, whose flags every service widens; a part before it keeps
            // the manifest as it was, so the parts still to merge are generated against the base they came from.
            Next = last ? next.Widened() : next,
            OnConflicts = current.WithPartInConflict(upgrade.To, all),
        };
        var code = await execution.RunAsync(step, options, start, ct);
        if (code == ExitCode.Conflicts)
        {
            var left = all.Count(p => !upgrade.Done.Contains(p));
            terminal.Info(last
                ? $"Conflicts in {part}, the last part of the upgrade to {upgrade.To}: resolve them, commit, then dotskit upgrade --continue repairs the usings, builds and finishes the upgrade."
                : $"Conflicts in {part}: {left} of {all.Count} part(s) of the upgrade to {upgrade.To} left - resolve them, commit, then continue with dotskit upgrade --continue.");
            return (ExitCode.Conflicts, null);
        }

        return (code, code == ExitCode.Done ? part : null);
    }

    /// <summary>
    /// The run after the last part was left in conflict and resolved: no file of the template changes; the usings of
    /// every move of the upgrade are repaired, the solution builds, and the manifest moves to the release.
    /// </summary>
    private async Task<ExitCode> FinishAsync(string root, Manifest current, UpgradeInProgress upgrade, IReadOnlyList<string> parts, Options options,
        TreeStart start, CancellationToken ct)
    {
        terminal.Info($"Finishing the upgrade from the template {current.Template} to {upgrade.To}: every part is merged; the usings are repaired and the solution builds.");
        var target = (current.WithTemplate(upgrade.To).Widened()) with { Upgrade = null };
        // Every part merged: the two trees of the step are the next output, and the merge has nothing to write but the manifest.
        var plan = await planner.BuildAsync(root, current with { Upgrade = null }, target, new Merging.MergeMode(options.Force, options.MarkBase), ct,
            new PartStep(upgrade.Done.ToHashSet(StringComparer.Ordinal), Part: "", parts));
        return await execution.RunAsync(plan with { Next = target }, options, start, ct);
    }
}
